"""Finite ambitions: authored decisions, work, proof and a lasting conclusion."""
def choice(label,reply):return (label,reply)
def step(title,kind,work,result,line,a,b,*,crowns=0,materials=None,magic=True):
    return dict(title=title,kind=kind,work=work,result=result,line=line,choices=[a,b],crowns=crowns,materials=materials or {},magic=magic)
def goal(title,want,why,room,keepsake,proof,ending,after,stages):
    return dict(title=title,want=want,why=why,room=room,keepsake=keepsake,proof=proof,ending=ending,after=after,stages=stages)

GOALS={
'mira':goal('An author on the title page','Recover and publish the complete masquerade comedy with its author correctly credited.',
 '“The catalogue calls Hester Vale a copyist. I think she wrote the play. I want a complete edition with the right name on it, and enough evidence that another reader can check my claim.”',
 'library','The Masquerade at Low Water — Hester Vale','A complete, bound edition with an attribution note and a recorded public reading.',
 'Mira places the finished edition on the shelf. Hester Vale’s name is on the title page; the evidence follows the text. She reads the dedication aloud, then runs a finger under the author’s name. “We did it. The play is complete, and she gets the credit.”',
 [choice('Ask which passage she rereads','“The captain delivering his grand speech to an empty balcony. I defended that scene through two drafts of the notes. Fortunately, Hester had already made it funny.”'),choice('Ask whether she still checks the attribution','“The evidence is in the edition. If new evidence appears, I will consider it. I am not going to reopen a finished book every morning to prove I still care.”')],[
 step('Locate the missing scenes','search','Compare the bindery inventory, borrow the missing folio and match its page numbers.','The missing scenes are recovered on loan and their page numbers match the surviving script.',
 '“Two folios have the same title. One is an adaptation. We need to know which belongs with our copy.”',choice('Compare the page numbering first','“Yes. A matching joke is tempting; matching catchwords would actually join the pages.”'),choice('Compare the handwriting and paper','“Then we record the different hands before deciding which one wrote the words.”')),
 step('Establish the author','cipher','Compare Hester’s signed draft, the dedication and the payment record.','The signed draft and payment record identify Hester Vale as author; later copyists receive separate credit.',
 '“The payment names Hester, but payment alone could mean copying. I want the draft checked as well.”',choice('Require both pieces of evidence','“Agreed. I would rather delay a correct claim than print it with the wrong reason.”'),choice('Ask her to credit the copyist too','“Yes. Recovering an author does not require making the copyist disappear.”')),
 step('Make the complete edition','repair','Prepare the corrected text, attribution note, illustrations and binding.','The text is complete and the bound edition distinguishes author, copyist and modern editors.',
 '“The notes are longer than the first act. I may have become carried away.”',choice('Put detailed notes at the back','“The comedy first. Readers who want the argument can turn to it afterward.”'),choice('Keep short notes beside difficult lines','“Short notes, then. Hold me to the word short when I reach the handwriting.”'),crowns=12,materials={'binding-thread':2}),
 step('Read and place the finished book','bargain','Arrange the reading, check the final copy and return the borrowed folio.','The reading reaches the final scene, the borrowed original is returned and the edition is placed in the library.',
 '“I would like to read the dedication. Would you introduce the play, or take the captain’s part?”',choice('Introduce Hester and the recovered play','“Give her the first sentence. We can put our own work in the second.”'),choice('Take the captain’s part','“Excellent. I expect a man who has confused command of a ship with command of an audience.”'),magic=False)
 ]),
'tamsin':goal('Tamsin’s table','Write, test, illustrate and bind an original cookbook, then serve its signature feast.',
 '“I repair other people’s books. I want to make one of my own: recipes I have actually cooked, with quantities that work and a binding that lies open beside a bowl. Then I want to feed you the feast on the last page.”',
 'kitchen','Tamsin’s Table — tested household recipes','The complete cookbook is bound and its four-dish feast is served.',
 'Tamsin signs the first copy of Tamsin’s Table. The mushroom pie holds its shape, the herb broth is clear and the pear tart has vanished from several plates. She sits down with her own serving. “Every recipe works. The book opens flat. We have finished it.”',
 [choice('Ask which recipe she is proudest of','“The pie. The first one could have been served through a funnel. I kept the failed quantities in my notes so I would not make that particular soup twice.”'),choice('Ask her to show you the binding','“See how it stays open without leaning on the thread? That was worth the extra sewing. Clean hands, please. I intend this copy to acquire its stains honestly.”')],[
 step('Choose and document the recipes','cipher','Choose four dishes, record their sources and write measured ingredients.','The book has four complete draft recipes: herb broth, mushroom pie, oat rolls and pear tart.',
 '“My notes say ‘enough flour’. A magnificent instruction if you already know the answer.”',choice('Measure a batch together','“Then we weigh before I put it in. You may confiscate the handful I am about to call a unit.”'),choice('Record what a cook should see and feel','“Both measurements and signs. The dough should be soft enough to fold, not merely weighed correctly.”')),
 step('Test the complete menu','repair','Cook trial batches, compare the results and revise the quantities.','All four recipes pass a second trial; the pie filling sets and the rolls bake through.',
 '“The pie tastes good and collapses when cut. I am not calling that finished because you are hungry.”',choice('Test a thicker filling','“I will reduce the broth and keep the crust unchanged. Then we will know what helped.”'),choice('Test a longer cooling time','“A proper timed test. If it works, the waiting time belongs in the recipe.”'),crowns=6),
 step('Illustrate and bind the cookbook','repair','Draw the useful preparation steps, proofread the recipes and sew a flat-opening binding.','Tamsin’s illustrated cookbook is bound with tested quantities and a usable index.',
 '“I can draw the pie looking splendid, or show where to cut the steam vents. There is room for one large picture.”',choice('Show the vents and add a small finished pie','“Useful and appetising. I can live with a smaller portrait of my finest pastry.”'),choice('Show a cut slice and label the texture','“Yes. A reader can compare the middle instead of guessing from the crust.”'),crowns=10,materials={'binding-thread':2}),
 step('Serve the signature feast','bargain','Buy the feast ingredients, share the kitchen jobs and serve all four dishes.','The feast is served from the finished recipes; Tamsin eats with her guests.',
 '“I want to cook the pie. Someone else must watch the rolls while I do it. This is a request, not a test of whether you notice me struggling.”',choice('Take responsibility for the rolls','“Thank you. The timer is yours. I shall resist inspecting it every thirty seconds.”'),choice('Arrange the serving and cleanup','“Then I can finish cooking and sit down. That is a very attractive division of labour.”'),crowns=8,magic=False)
 ]),
'iona':goal('Three roads, one atlas','Publish a tested travellers’ atlas of the bindery, waterworks and nursery roads.',
 '“I want a traveller to reach these three places using my book. Every crossing checked, every shelter described honestly. I will include the music houses, but they do not excuse a missing bridge.”',
 'command-room','Iona’s Three-Road Atlas','All three routes are surveyed and a courier completes the final route using the finished atlas.',
 'The courier returns with the atlas open at the final turning. Every marked crossing and shelter was where Iona said it would be. She writes the verification date inside the cover. “Three roads checked. A stranger followed the last one without me pointing. It is finished.”',
 [choice('Ask whether the music houses made it in','“Three of them. Opening hours, wet-weather shelter and which one expects you to join the chorus. Accurate travel information.”'),choice('Ask where the courier hesitated','“At the nursery fork. I enlarged the mill marker before binding the final copy. That correction is already made; you are holding the finished edition.”')],[
 step('Survey the bindery road','crossing','Walk the bindery road, measure the footbridge and confirm the stopping places.','The bindery road has verified distances, a safe crossing and shelter permission.',
 '“The old map calls it a bridge. A person pushing a handcart would call it a surprise.”',choice('Measure the usable width','“And the turning space on both banks. A cart has to leave the bridge as well as enter it.”'),choice('Mark the pedestrian route and cart detour separately','“Good. Two honest routes are better than one line that lies to half its readers.”')),
 step('Survey the waterworks road','water','Check the flood marks, clear the walking channel and record the high-water detour.','The waterworks route records the flood limit and a verified dry detour.',
 '“It is dry today. That tells us almost nothing about the week someone will need this map.”',choice('Use the flood marks to define a closure point','“Then the warning tells someone when to turn back, not merely that water has been seen here.”'),choice('Ask the keeper to walk the detour with us','“A report becomes much more useful when we have put our own boots on it.”')),
 step('Survey the nursery road','search','Verify the nursery forks, refuge and music-house opening hours.','The nursery route has checked landmarks and an agreed refuge; optional music stops are marked separately.',
 '“There is a fiddler two streets from the refuge. I am putting her in the atlas, but I promise to mark the extra distance.”',choice('Keep the direct route prominent','“Yes. Nobody should miss their bed because I fancied another tune.”'),choice('Add the music stop as a clearly measured detour','“That is exactly the sort of unnecessary detail I want to do properly.”')),
 step('Bind and independently test the atlas','repair','Bind the three surveys, send a courier along the nursery route and incorporate the returned corrections.','An independent courier follows the finished atlas successfully; the corrected edition is bound.',
 '“I must not walk beside the courier explaining the unclear parts. The book has to do its own work.”',choice('Ask the courier to mark every hesitation','“Even the small ones. Especially the small ones I think are obvious.”'),choice('Have the courier explain the route back from the book','“A useful check before departure. After that, I put the pen down until the report comes back.”'),crowns=14,materials={'binding-thread':2})
 ]),
'aurelia':goal('The four-station signal chain','Build a working signal-lantern chain between the castle and three roadside refuges.',
 '“I want a warning sent from the far refuge to reach us, and an answer to reach them. Four working stations, clear signals and people who can operate them without waiting for me.”',
 'guard-barracks','The four-station signal chain','Every station receives and returns the correct signal during a complete night test.',
 'Three distant lanterns answer in order. Aurelia checks the last acknowledgement and closes the test sheet. The keepers have operated every station correctly. “The chain works. They did not need me beside the shutters.” She sits down to watch the lights go out for the night.',
 [choice('Ask about the last acknowledgement','“Correct on the first attempt. I wanted to send it twice. The keeper reminded me that the agreed signal had already arrived.”'),choice('Invite her to look at the stars','“Gladly. Tonight the lamps have assigned keepers, and I have a chair.”')],[
 step('Choose the signal positions','search','Survey sight lines between the castle and three agreed refuge stations.','Four station positions have clear sight lines and keeper permission.',
 '“The highest roof has the best view and the worst access. Someone will need to reach it in rain.”',choice('Choose the lower accessible platform','“Then we trim the obstructing branches with permission. A signal nobody can reach is decorative.”'),choice('Repair safe access to the higher position','“Rails and a sound ladder before any lantern goes up. I will put that in the plan.”')),
 step('Build and fit the lanterns','repair','Build four shuttered lamps and fit weather covers and stable mounts.','All four lamps are mounted and their shutters remain readable in poor weather.',
 '“A beautiful flame is useless if the shutters jam. I want the plain mechanism tested wet.”',choice('Prioritise the shutter test','“Good. Then we know what we are protecting when we fit the covers.”'),choice('Make the spare handles interchangeable','“Yes. A keeper should not need the original maker to replace one.”'),crowns=24,materials={'sun-amber':2,'binding-thread':2}),
 step('Train the station keepers','cipher','Write three signal patterns and practise sending, reading and acknowledging them.','Each keeper sends, reads and acknowledges the agreed signals without prompting.',
 '“One keeper has suggested a clearer pause between signals. I have used my version for years.”',choice('Test her proposed pause','“Years of habit are not evidence that it is the best interval. We can time both.”'),choice('Ask a new reader to compare both versions','“Someone who has not learned my mistakes yet. An excellent choice.”')),
 step('Run the night test','bargain','Schedule the keepers and send the complete warning-and-answer sequence through all four stations.','The night test succeeds at every station; the operational rota is accepted.',
 '“I want to stand at the far station. That is also the one whose keeper has just passed every test.”',choice('Stay at the castle and let the keeper operate it','“Yes. I can watch the answer from here and resist imagining that distance makes her forget the shutters.”'),choice('Ask each keeper to sign the test result','“Then their work is recorded under their own names. I will sign for the castle station.”'),magic=False)
 ]),
'neris':goal('Neris’s elemental grotto','Build a sheltered elemental grotto where Neris can disperse and reform safely.',
 '“I want a room whose water is part of the room, not something carried to a tub. Warm channels, a quiet basin and a ward that keeps my dispersed water together. I would like to stop holding a human outline for a while.”',
 'hot-spring','Neris’s elemental grotto','The circulation and containment tests pass; Neris disperses and reforms safely in the completed grotto.',
 'Neris loosens into clear water and flows through the completed channels. After a long, quiet circuit she gathers herself beside the basin. “Every part of me came back together. The current felt right.” She smiles at the finished chamber. “This is the place I wanted.”',
 [choice('Ask what it feels like to use the grotto','“There is room to move without choosing elbows first. I know where I am in the current. That took more careful channel work than the graceful description suggests.”'),choice('Ask whether she would like company here','“Yes, today. Sit beside the warm basin. Ask before entering the water when I have dispersed; it is rather more personal than sharing a bath.”')],[
 step('Find and survey the chamber','search','Survey the spring-side cavity and measure its source, overflow and stable floor.','A stable chamber beside the hot spring has a measured source and a separate overflow.',
 '“That narrow cleft has a lovely echo. It also loses water into the rock. I do not want to lose part of myself with it.”',choice('Choose the sound, wider cavity','“Less dramatic and much more comfortable. We can make our own interesting sounds.”'),choice('Map every outlet before deciding','“Yes. I want the complete route back, not a promise that water usually finds one.”')),
 step('Shape the channels','water','Clear the channels, line the basin and regulate the incoming heat.','The basin holds water and the warm return channels circulate without sudden cold pockets.',
 '“The fast channel looks impressive. Against my dispersed form it would feel like somebody repeatedly tugging my sleeve.”',choice('Use broad, slow curves','“That is what I hoped you would understand. Movement can be pleasant without being forceful.”'),choice('Make the stronger current an optional side channel','“With a gate I can reach from the basin. Sometimes I may want it; it must be my choice.”'),crowns=24,materials={'porous-clay':4}),
 step('Fit and test the gathering ward','cipher','Inscribe a basin-bound gathering ward and test it with marked water before Neris enters.','The ward returns all marked test water while leaving the overflow safe and separate.',
 '“The ward should help me gather. It must not hold me here when I decide to leave.”',choice('Test the release before the full circuit','“Please. An effective exit is part of a successful ward.”'),choice('Give Neris the release control','“Then I can stop without waiting for someone else to interpret a ripple.”'),crowns=18,materials={'moon-glass':2,'binding-thread':2}),
 step('Complete the first full circuit','water','Run the warmed circulation, let Neris test dispersal and record her safe return.','Neris completes a full dispersed circuit and reforms safely; the grotto is ready for use.',
 '“The equipment passed. This next test is mine. Will you watch the return marker, or wait by the release?”',choice('Watch the return marker','“Thank you. Tell me what you see without reaching into the channel.”'),choice('Wait beside the release control','“I will give the agreed signal if I need it. Until then, let me enjoy finding out.”'),magic=False)
 ]),
'sabine':goal('The necklace she came back for','Recover Sabine’s silver-and-garnet necklace and settle its ownership.',
 '“My former partner kept my share of a job and sold the necklace I had bought with it. I want it back. I liked it before it became evidence of anybody’s character. The clasp has a little fox on it.”',
 'vault','Sabine’s fox-clasp necklace','The genuine necklace is recovered and the competing claim is resolved in writing.',
 'Sabine turns the clasp over: the tiny fox has one worn ear, exactly as she remembered. The settlement is signed and the necklace is hers. She fastens it herself. “We got it back. I intend to enjoy wearing it before anyone asks me to make a lesson of it.”',
 [choice('Ask to see the fox clasp','“One worn ear, a scratched nose and an excellent grip. You may look. I am keeping it on.”'),choice('Ask whether she still thinks about the former partner','“Occasionally. Much less often than I think about which collar shows the garnets properly. That is a considerable improvement.”')],[
 step('Trace the sale','search','Compare fence receipts and locate the dealer who handled the fox-clasp necklace.','The sale trail identifies the collector currently holding the necklace.',
 '“I know two dealers who might answer. One likes money. The other likes being right about a rival.”',choice('Ask for the transaction record directly','“Plain questions first. If I start offering compliments, remind me that we came for a date and a name.”'),choice('Compare the dealers’ accounts','“And keep the insults out of the notes. Some of them deserve preservation, but in another book.”')),
 step('Prove which necklace is hers','cipher','Compare Sabine’s purchase receipt, the clasp sketch and the collector’s inventory.','The receipt and concealed clasp mark identify the genuine necklace; the collector bought it without knowing the dispute.',
 '“The collector paid honestly. I dislike discovering a reasonable person at the end of an excellent grievance.”',choice('Ask Sabine to explain her own part plainly','“I took work I should have questioned. I still bought this necklace with an agreed share. Those are separate facts, and you may ask about either.”'),choice('Check the collector’s receipt too','“Fair. I want the genuine necklace, and I will not call a forged claim convincing because it favours me.”')),
 step('Negotiate the return','bargain','Arrange the collector’s reimbursement from the former partner’s disputed deposit and pay the registry fee.','The collector accepts the documented reimbursement; the registry records Sabine’s title.',
 '“We have enough evidence to claim the held deposit. I could still pick the case lock. I would rather leave with a necklace I can wear openly.”',choice('Pursue the recorded settlement','“Then I shall exercise the rare art of leaving a tempting lock alone.”'),choice('Buy it directly for 32 crowns instead','“A more expensive way to end the wait. He signs the transfer, and I pursue my former partner’s debt separately.”'),crowns=12,magic=False),
 step('Recover and inspect the necklace','repair','Collect the necklace, check the hidden mark and repair its worn safety catch.','The genuine necklace is returned, its catch is sound and the ownership dispute is closed.',
 '“The fox still has its crooked ear. Shall we keep the old catch behind a new safety loop, or replace the worn spring?”',choice('Keep the fox and fit a discreet safety loop','“Good. I want to recognise it, and I want it to remain around my neck.”'),choice('Replace only the hidden spring','“Practical and invisible. I promise to give the invisible work its due praise.”'),crowns=6,materials={'binding-thread':1})
 ]),
'koharu':goal('The dragon takes a bow','Build a portable puppet theatre and perform its first complete show.',
 '“I want a stage I can fold, carry and put up again without swearing at it. And a wooden dragon who can raise one offended eyebrow. The show ends when the dragon learns the princess has already hired a locksmith.”',
 'workshop','Koharu’s travelling puppet theatre','The portable stage is set up successfully and the complete show reaches its final curtain.',
 'The wooden dragon raises its eyebrow exactly on cue. The locksmith gets the last line and the curtain falls without catching a string. Koharu steps out from behind the stage and bows. “It travelled, it stood up, and we finished the show. I made a theatre.”',
 [choice('Ask whether the dragon has become demanding','“He requires one dry box and an audience prepared to question his legal claim to princesses. Very manageable terms.”'),choice('Ask to try the eyebrow control','“One finger, gently. Yes, that expression. You have just accused the entire room of poor craftsmanship.”')],[
 step('Build the folding stage','repair','Fit the folding frame, braces and replaceable hinges.','The stage folds into two carryable sections and stands without a wobble.',
 '“I could add a second balcony. I have not yet made the first one fit in the carrying case.”',choice('Finish the single-level frame first','“A cruelly sensible production note. The dragon will have to be indignant on one floor.”'),choice('Draw the balcony as a later addition','“Then I can keep the idea without making tonight’s hinges responsible for it.”'),crowns=18,materials={'binding-thread':2}),
 step('Make the cast and controls','repair','Carve the puppets, fit their controls and practise their distinctive movements.','The dragon, princess and locksmith can move and speak without tangled controls.',
 '“The princess’s operator wants a simpler wrist joint. I like the complicated one rather a lot.”',choice('Let the operator test both joints','“Yes. It is her hand inside the puppet. Admiring my mechanism is not a performance requirement.”'),choice('Keep the complicated joint for the dragon','“He already thinks himself superior. An extra hinge will suit him.”'),crowns=12,materials={'porous-clay':2}),
 step('Rehearse the whole show','cipher','Finish the script, assign the parts and rehearse every cue through the final curtain.','The complete script and cue sheet are tested; each performer agrees to their part.',
 '“The funniest joke is about someone in the household. She has not heard it yet.”',choice('Ask her permission before keeping it','“Yes. Laughing at the rehearsal is not permission on her behalf.”'),choice('Give the joke to the fictional magistrate','“He has an inexhaustible capacity to deserve it. I shall change the hat as well.”')),
 step('Travel, set up and perform','crossing','Carry the packed stage to the common room, assemble it and perform the complete show.','The transported stage works and the show reaches its final curtain with every puppet intact.',
 '“I have checked the catches twice. I would like you to watch the show now, rather than watch me check them a third time.”',choice('Take a seat and enjoy it','“Front row, if you wish. You have earned an excellent view of the eyebrow.”'),choice('Take the agreed supporting part','“Your cue is after the dragon says impossible. Please make the locksmith sound delighted.”'),magic=False)
 ]),
'zahra':goal('Zahra’s masterpiece','Forge and prove an original masterpiece weapon, the steel sword Emberline.',
 '“I want to make a sword worth signing with my whole name. Balanced for a real hand, tough at the spine, precise at the edge, with an ember channel that does exactly what I designed. I have repaired enough other people’s compromises.”',
 'smithy','Emberline — Zahra’s masterpiece','The completed sword passes balance, edge and ward-load trials and receives Zahra’s maker’s mark.',
 'The last test block parts cleanly. The blade stays true and the controlled ember channel dims when Zahra releases it. She stamps her maker’s mark near the hilt. “Emberline. Finished, tested and mine to sign.” She lays the sword in its fitted case, unable to stop smiling.',
 [choice('Ask which part took the most work','“The grip. Everyone looks at the edge. A hand that tires after six swings will ruin the finest edge in the room.”'),choice('Ask about the music box on her bench','“Still a hobby, and still missing a bird with a respectable beak. A completed sword does not require me to give up small pleasures.”')],[
 step('Set the weapon’s design','cipher','Draw a steel field sword with a fitted grip and a measured ember channel.','The design specifies balance, grip size, edge geometry and a bounded ember channel.',
 '“A heavy blade would impress someone lifting it once. I want someone to use it all afternoon.”',choice('Prioritise balance and repeated use','“Then we test a weighted wooden pattern before wasting steel on my pride.”'),choice('Ask her to state the limits of the enchantment','“A controlled force inscription. It will not cut every ward ever made. I want an excellent weapon, not a dishonest advertisement.”')),
 step('Forge and fit the blade','repair','Forge the steel blank, temper the edge and fit the grip against the tested pattern.','The tempered blade is straight and the fitted grip balances at the marked point.',
 '“There is a fault near the tang. Small enough to hide under the grip. Large enough to reject.”',choice('Remake the faulty section','“Yes. I would recognise it every time somebody trusted the hilt.”'),choice('Keep the rejected piece as a test sample','“Then it can teach us something after it has failed to become a sword.”'),crowns=36,materials={'fireglass':2,'watch-iron':2}),
 step('Inscribe the ember channel','cipher','Fit the bounded inscription and test its response under measured load.','The ember channel responds to deliberate force and shuts down when released.',
 '“I can make it brighter. That is not the same as making it better.”',choice('Keep the restrained, repeatable output','“My choice too. If I want applause for a flame, I can light the forge.”'),choice('Test shutdown before increasing the load','“Good. A weapon should remain something its wielder can put down.”'),crowns=24,materials={'sun-amber':2,'moon-glass':2}),
 step('Prove and sign Emberline','repair','Test the sword against fixed targets, inspect it after repeated swings and stamp the accepted blade.','Emberline passes the balance, edge and inscription trials and is signed by Zahra.',
 '“This is the part I have been avoiding with stories. I want it to pass. I want you to tell me if it does not.”',choice('Read the test results aloud without embellishment','“Please. I can supply the proud speech after the figures are in.”'),choice('Ask her to perform the final trial herself','“Yes. My design, my hands. Stay where you can see the edge return.”'),magic=False)
 ]),
'fenna':goal('The castle festival','Organise and finish the castle’s first household festival of games, music and supper.',
 '“I want to put on a festival people remember as a good day here. A treasure hunt, a ridiculous relay and music after supper. Three things we actually finish, with enough help that I can join one.”',
 'common-room','The first castle festival programme','The hunt, relay and music evening all finish, followed by a closing toast.',
 'The last chorus ends with several people on the wrong note and nobody pretending otherwise. The hunt prizes have owners, the relay ribbons are tied and the supper dishes are cleared. Fenna raises her cup. “We did the whole programme. I even got to lose the relay myself. That was a festival.”',
 [choice('Ask about losing the relay','“An appalling injustice caused by somebody else running faster. I am considering a strongly worded compliment.”'),choice('Ask which part she would keep next time','“The quiet table beside the music. Three people used it and still stayed for the final song. That belongs in the finished programme’s notes.”')],[
 step('Set the programme and enlist help','bargain','Choose three activities, ask residents which jobs they want and agree a manageable programme.','The hunt, relay and music evening have agreed helpers and a clear timetable.',
 '“I had seven ideas. I also had a pencil powerful enough to cross out four of them.”',choice('Keep the three she most wants to join','“The hunt, relay and music, then. I refuse to spend my entire festival announcing someone else’s fun.”'),choice('Leave breaks between the activities','“Yes. A programme should survive somebody wanting another cup of tea.”'),magic=False),
 step('Make the games safe and fair','crossing','Check the hunt area, repair the relay crossing and test the rules.','The hunt clues are solvable and the relay course has a sound crossing and fair starts.',
 '“One shortcut is excellent for people with my stride. Less excellent for almost everybody else.”',choice('Change the course to equalise the distance','“Done. If I win, I want to be insufferable with a clear conscience.”'),choice('Make the shortcut a separate optional challenge','“That can have its own ribbon. Nobody loses the main race for choosing the safe turn.”'),crowns=8,materials={'binding-thread':2}),
 step('Prepare supper and music','repair','Prepare decorations, tune the borrowed instruments and buy the agreed supper supplies.','The common room is ready, the musicians know the order and supper supplies are paid for.',
 '“Someone has asked for a louder finale. I like the idea. I also promised a quiet place to sit.”',choice('Keep a quiet table away from the players','“And tell people where it is. An unannounced quiet corner is just an empty chair.”'),choice('Keep the finale short and announce it','“One cheerful racket, with a clear ending. That sounds like my sort of restraint.”'),crowns=16),
 step('Hold the festival','bargain','Run the hunt and relay, serve supper and finish the music evening with a closing toast.','All three festival activities finish and Fenna takes part in the relay herself.',
 '“The helpers are ready. Tell me to hand over the whistle before I accidentally become the whole organising committee again.”',choice('Take the whistle for her relay heat','“Thank you. Prepare an impartial expression for when I dispute the result.”'),choice('Ask the agreed helper to start the race','“Right. I asked her because she wanted the job. I can let her do it.”'),magic=False)
 ]),
'kaede':goal('The regional champion','Qualify for and win the regional three-bout fighting tournament.',
 '“I want the regional title. I enjoy teaching, and I still want to stand in a ring with someone trying honestly to beat me. We will use the tournament’s practice weapons. No hidden spells, no excuses about the rules afterward.”',
 'training-yard','Regional champion’s trophy','Kaede wins the qualifying bout, semifinal and final under the published tournament rules.',
 'The judge raises Kaede’s hand after the third scoring touch. Her opponent offers a clasp, and she accepts it before taking the trophy. “I won.” She looks down at the engraved title and laughs. “I have prepared much longer speeches. That is the one I want first.”',
 [choice('Ask about the final opponent','“She nearly caught the second feint. I won because I reset my stance instead of chasing the first opening. I will remember her name when I teach that.”'),choice('Ask where the trophy belongs','“The training-yard shelf. At a height where I can admire it without pretending to inspect something else.”')],[
 step('Enter and choose a training plan','bargain','Register for the tournament, inspect the practice weapons and learn the scoring rules.','Kaede is registered and the equipment passes the judge’s inspection.',
 '“Three scoring touches. A clean reset after each. The judge will not care that a flourish looked magnificent.”',choice('Practise clean touches and resets','“Unromantic, useful and exactly what I need to stop neglecting.”'),choice('Study the likely opponents before training','“Then we watch complete bouts, including the boring recoveries where people actually lose.”'),crowns=12,magic=False),
 step('Win the qualifying bout','crossing','Practise distance against the qualifier’s long reach, then contest the qualifying bout.','Kaede draws the long-reach attack, steps inside the recovery and wins the qualifier three touches to one.',
 '“He reaches me before I expect. I keep trying to prove I can reach farther.”',choice('Practise drawing the attack before closing','“Yes. I can make his reach commit him instead of arguing with its length.”'),choice('Practise staying outside until the reset','“Patience, then a clean entry. Count the moments when I start rushing.”'),magic=False),
 step('Win the semifinal','crossing','Train a response to the semifinalist’s changing tempo and fight the semifinal.','Kaede stops following the false rhythm and wins the semifinal three touches to two.',
 '“She changes pace after every second exchange. I have been complimenting the trick while falling for it.”',choice('Break the rhythm with a full retreat','“A retreat I choose. I can afford to give her empty ground.”'),choice('Watch her feet instead of the practice blade','“That will spoil the pretty distraction. Good. I am here to win.”'),magic=False),
 step('Win the final','crossing','Rehearse the finalist’s counter, rest between practice sets and contest the title bout.','Kaede counters the finalist’s feint, wins the third scoring touch and is awarded the regional title.',
 '“The finalist punishes a second attack. I want to make one anyway, which probably explains her success.”',choice('Practise one clean attack and a reset','“Hold me to it. I want the trophy more than I want to indulge that habit.”'),choice('Make the second movement a withdrawal','“Let her counter an opening that has already gone. Yes. Let us drill that until I stop admiring it and can do it.”'),magic=False)
 ]),
'elowen':goal('Three treatments in one case','Finish a tested field-remedy kit for manticore venom, wyvern venom and basilisk stiffness.',
 '“I want three labelled treatments in a case a field party can use. Two antivenoms, one preparation for basilisk stiffness. A closing wound does not mean the venom has stopped. I want the instructions and the remedy to be ready before someone needs them.”',
 'infirmary','Elowen’s three-treatment field kit','The three preparations pass separate tests and the first complete, labelled kit is packed.',
 'Elowen places the three labelled preparations in their fitted case and checks the instructions against the test record. Each has passed its own test. “Manticore, wyvern, basilisk. All three ready.” She closes the case. “We finished the kit. Now a party can actually take it with them.”',
 [choice('Ask why the bottles have different closures','“So a cold or hurried hand can distinguish them. The labels still need reading. A good case helps somebody follow an instruction; it does not ask them to guess.”'),choice('Ask whether she has put her work away','“The finished formulae are filed. I am going to look at the yellow flowers before I find an excuse to check a fourth label.”')],[
 step('Specify the tests and labels','cipher','Write separate treatment targets, handling instructions and checks for all three preparations.','Three distinct test sheets separate venom neutralisation from relief of stone stiffness.',
 '“Basilisk stiffness is not venom. I will not put one reassuring word on three different problems.”',choice('Give each preparation its own test','“Exactly. Success against one sample tells us nothing about the next.”'),choice('Have a reader explain the labels back','“Then I learn what the instruction actually says to somebody who did not write it.”')),
 step('Prepare the manticore antivenom','repair','Use a recovered manticore spine to test a silver-ivy preparation in sealed sample vessels.','The manticore preparation neutralises the venom sample and passes a repeated preservation check.',
 '“The first mixture worked immediately and failed after storage. A field bottle must survive the journey.”',choice('Test the stored mixture again before accepting it','“Yes. I want the result from tomorrow’s bottle, not yesterday’s promising moment.”'),choice('Improve the seal and repeat the same test','“One change, then a comparison. We can tell whether the seal actually helped.”'),materials={'manticore-spine':1,'silver-ivy':2,'porous-clay':1}),
 step('Prepare the wyvern antivenom','repair','Compare the dried wyvern sample with the first formula and prepare the distinct wyvern treatment.','The separate wyvern formula passes its sample and storage tests.',
 '“The manticore formula does not pass this test. Similar symptoms have not given us the same treatment.”',choice('Keep the failed comparison in the record','“With a clear warning. Another maker should not repeat this merely because the bottle looked familiar.”'),choice('Give the new preparation a distinct closure','“A useful physical difference, beside an explicit label. We will test that with gloves.”'),materials={'wyvern-venom-crystal':1,'silver-ivy':2,'porous-clay':1}),
 step('Prepare the basilisk treatment','cipher','Test a scale-based ward dressing against a controlled stiffness trace and write its limits.','The basilisk dressing releases the test stiffness; its instructions distinguish it from the two antivenoms.',
 '“This loosens the stiffness. It does not make somebody immune to looking at a basilisk again.”',choice('Put that limit on the first line','“Yes. A successful treatment must not encourage the next injury.”'),choice('Add a reminder to break line of sight','“That belongs beside the treatment step. Stop the cause while treating its effect.”'),materials={'basilisk-scale':1,'silver-ivy':2,'binding-thread':1}),
 step('Pack and independently check the kit','repair','Fit the case, repeat the three checks and have another reader follow the instructions.','All three preparations and their instructions pass; the first complete kit is packed.',
 '“Please read the card exactly as written. If you have to ask me what a sentence means, I have more writing to do.”',choice('Follow the card without asking for hints','“Thank you. I will listen instead of explaining over the problem.”'),choice('Read it as though working in poor light','“Then we will learn whether my small, tidy lettering was a mistake.”'),crowns=12,materials={'binding-thread':2},magic=False)
 ]),
'nyssara':goal('Nyssara’s enchanting manual','Publish an enchanting manual an apprentice can use to make a working ward without her intervention.',
 '“I want an apprentice to make the reading-lamp ward from my book while I keep my mouth shut. The instructions must survive my absence. That is a more demanding test than finding somebody polite enough to praise them.”',
 'enchanting-room','Nyssara’s Practical First Enchantments','An independent learner follows the completed manual and makes a functioning reading-lamp ward.',
 'The apprentice dims the lamp, restores its light and releases the ward without asking Nyssara for help. Every check passes. Nyssara signs the final edition and adds the testers’ names. “It works without me. That is what I set out to write.”',
 [choice('Ask about the apprentice’s correction','“Page six. I had omitted a return stroke I make automatically. Her question found it. Her name is beside the correction.”'),choice('Ask whether she enjoyed staying silent','“No. I enjoyed the result. The distinction will sustain me through the next demonstration.”')],[
 step('Choose and document the working example','cipher','Document a bounded reading-lamp ward with materials, marks and release instructions.','The draft covers construction, use and release of one complete reading-lamp ward.',
 '“My first draft starts with three pages on disputed terminology. The apprentice wants to know where to put the chalk.”',choice('Start with the complete worked example','“Then I can put the terminology after something the reader has actually seen.”'),choice('Separate required steps from optional explanations','“Yes. The reasoning remains available, and the first line becomes useful.”')),
 step('Expose the missing instructions','repair','Ask a learner to follow the draft while recording every unanswered question.','The trial identifies a missing return stroke and an ambiguous release instruction.',
 '“She asked what obvious meant. I had written it twice. Neither occurrence survived being asked aloud.”',choice('Thank her for identifying the gaps','“I will. A useful question deserves an answer before it receives my embarrassment.”'),choice('Ask Nyssara to attempt the steps exactly as printed','“A severe but fair experiment. I may discover that I have never actually followed my own page.”')),
 step('Revise and bind the manual','cipher','Correct the diagrams, add the release test and credit the people who found the gaps.','The bound manual includes corrected diagrams, explicit limits and tester credits.',
 '“The apprentice wants her name in small letters. She thinks finding a mistake is impolite.”',choice('Ask how she wants her contribution described','“Good. Credit can be precise without becoming a ceremony she did not ask for.”'),choice('Explain why the correction belongs in the record','“Because it improved the book. I can say that without making her responsible for my feelings about it.”'),crowns=16,materials={'binding-thread':2,'moon-glass':1}),
 step('Pass the independent ward test','repair','Provide the finished manual and materials, then observe an independent construction and release.','The apprentice builds, operates and releases the reading-lamp ward using only the finished manual.',
 '“I am allowed to stop an unsafe action. I am not allowed to rescue an unclear sentence with a lecture.”',choice('Record questions without supplying answers','“If the book answers them, she can find the answer. If it does not, the test has found work for me.”'),choice('Observe the final operation and release','“Both. A lamp that turns on but cannot be put out would be an unusually clear failure.”'),materials={'porous-clay':1,'sun-amber':1},magic=False)
 ]),
'sylva':goal('The silverleaf’s first seeds','Grow a rare silverleaf night-flowering tree from seed to bloom and viable seed.',
 '“I have found a nursery willing to spare one silverleaf seed. I want to raise it here until it flowers and gives us viable seeds of our own. A living tree at the end, not a tray of attempts I keep calling promising.”',
 'conservatory','The flowering silverleaf tree','The established tree flowers and its collected seeds pass a germination test.',
 'The silverleaf flowers open after dusk. Sylva leaves them on the tree until the seed pods mature, then shows you the first germinated seed from her carefully labelled tray. “A tree, flowers and another living seedling. We have grown it through the whole cycle.”',
 [choice('Ask whether the first seedling has a place','“Yes. Far enough from its parent for both sets of roots. I have learned to leave an unexciting amount of space.”'),choice('Sit with her beside the flowers','“Please. There is nothing we need to count tonight. I would like to look at what we grew.”')],[
 step('Obtain the seed and growing record','bargain','Arrange a nursery exchange and obtain the silverleaf seed with its recorded growing conditions.','The seed arrives with a dated nursery record and agreed permission to propagate it.',
 '“They offered a larger packet without records. One well-documented seed gives me a better chance than six guesses.”',choice('Choose the documented seed','“Then we know what conditions to reproduce, and which differences are ours.”'),choice('Ask about their failed germination attempts too','“Yes. A failure with a date and a temperature is useful information.”'),crowns=12),
 step('Germinate it in a prepared bed','water','Prepare the drained bed, reproduce the recorded seed conditions and check the emerging roots.','The silverleaf seed germinates and establishes a healthy root system.',
 '“The corner would look fuller with another plant. The tree will need that soil later.”',choice('Keep the root space clear','“Good. Empty space can be part of a finished planting plan.”'),choice('Use movable pots outside the root bed','“Then the colour can change without another excavation.”'),materials={'porous-clay':2,'living-root-fibre':1}),
 step('Bring the tree to its first bloom','cipher','Follow the nursery’s bounded seasonal ward and verify each growth stage before the next.','The controlled seasonal sequence produces a mature, healthy tree with flower buds.',
 '“The growth ward can shorten the waiting. It cannot replace water or tell us that unhealthy roots are ready.”',choice('Check the roots before each seasonal change','“Yes. We advance the season only after the plant is ready for it.”'),choice('Keep a comparison cutting outside the ward','“Then we have something to compare, instead of admiring speed as though it proved health.”'),crowns=18,materials={'sun-amber':2,'silver-ivy':2}),
 step('Collect and germinate the next generation','search','Observe the night flowers, allow seed pods to mature and test the collected seed.','The tree blooms and one collected seed germinates, proving successful propagation.',
 '“I want to cut a flower to keep. I also need these first flowers to finish making seed.”',choice('Draw the flower and leave it on the tree','“I can keep the drawing tonight and the seed later. A satisfying compromise.”'),choice('Keep a naturally fallen petal instead','“That copper edge is worth keeping. The flower has finished with it before I take it.”'),magic=False)
 ]),
'velis':goal('Velis’s supply-route charter','Establish a contracted route from the western market and receive its first fully accounted caravan.',
 '“I want a western-market route that brings what we ordered, pays the people who carry it and can explain a delay before it becomes a missing wagon. Three agreements and one complete delivery will prove whether I have built it.”',
 'warehouse','The western-market supply-route charter','Supplier, carrier and refuge agreements are signed and the first cargo and payments reconcile.',
 'Velis checks the last crate against the invoice. The carrier is paid, the refuge fee is recorded and every promised item is present. She closes the ledger. “The first delivery is complete. The route exists beyond my correspondence.” Then she pours tea for the people who brought it.',
 [choice('Ask whether the accounts balanced','“Exactly. I have already checked. You may now ask whether I enjoyed meeting the driver’s daughter. I did; she negotiates pears with alarming confidence.”'),choice('Ask about the next delivery','“Booked under the standing terms. That is what the finished route is for. Today I can discuss something other than inventing it.”')],[
 step('Agree the supplier’s terms','bargain','Set a modest repeat order with a western-market supplier, prices, substitution rules and written liability for shortages.','The supplier signs a repeat order with explicit prices and shortage responsibility.',
 '“The cheap offer charges the driver for missing goods he never packed. I know why it is cheap.”',choice('Require the supplier to own packing errors','“Yes. We can negotiate the price openly instead of hiding it in someone else’s wages.”'),choice('Request sealed, counted crates at collection','“A useful check, with the cost in the contract where both sides can see it.”'),crowns=12,magic=False),
 step('Contract the carrier','bargain','Agree the route, fair carriage fee, delay reporting and safe load limit.','The carrier signs a paid route with a safe load limit and a clear delay message.',
 '“He can promise a faster run if he overloads the wagon. I would rather receive the wagon.”',choice('Keep the safe load and realistic arrival window','“Then I can tell the household when to expect supplies without borrowing luck.”'),choice('Arrange two lighter consignments under one agreement','“That costs more carriage and less risk. We will write both figures down.”'),crowns=12,magic=False),
 step('Secure the refuge agreement','repair','Repair the agreed loading shelter and confirm water, overnight access and the refuge fee.','The route has a usable shelter and a signed refuge agreement.',
 '“The keeper asked who fixes the roof after a storm. Nobody had put that sentence in the draft.”',choice('Set a shared repair responsibility','“A percentage and a response time. Goodwill can help, but it does not buy shingles by itself.”'),choice('Include a paid maintenance allowance','“Then the keeper has the money before the first leak becomes our emergency.”'),crowns=16,materials={'binding-thread':2}),
 step('Receive and reconcile the first caravan','search','Receive the cargo, compare all three agreements and settle the signed delivery account.','The first caravan arrives with its contracted cargo and every agreed payment is settled.',
 '“I want to count the crates first and thank the people second. Remind me that both are part of receiving a delivery.”',choice('Check the cargo with the driver','“Together, then. A discrepancy found in front of both parties is much easier to settle.”'),choice('Prepare the account and welcome before arrival','“You handle the cups while I handle the receipts. Then I will put the receipts down.”'),crowns=12,magic=False)
 ]),
'rhess':goal('The watch handed over','Restore the old tower’s warning system and hand the watch to an agreed relief team.',
 '“I want to leave the old tower knowing who answers its warning. Repair the signal, test it, name the relief keepers and finish the handover. Then I can put my own watch record away.”',
 'guard-barracks','The tower handover record','The warning passes its test and the relief keepers explicitly accept the working watch.',
 'The warning rings from the repaired tower. The new keeper returns the agreed answer and signs the handover beside Rhess’s name. She waits for the final acknowledgement, then closes her old watch book. “They have the watch. I have handed it over.” She leaves by the road toward home.',
 [choice('Ask whether she went back to check','“For an agreed visit, yes. I asked the keeper how it was going. I did not take her place. The distinction was easier with the signed record in my pocket.”'),choice('Ask about the carved bird on her shelf','“It stayed here while I visited the tower. A small object, but I liked coming back to it.”')],[
 step('Survey the unfinished watch','search','Inspect the tower, record the remaining hazards and identify the people who still rely on its warning.','The remaining hazards and warning recipients are recorded; obsolete duties are separated from current needs.',
 '“The old book lists six posts. Two roads no longer exist. I have kept copying all six.”',choice('Verify which roads still need a warning','“Then I can close an obsolete entry because we checked it, not because I grew tired of reading it.”'),choice('Ask the current travellers what they need','“A clear warning at the active crossing. That is a task someone can actually inherit.”')),
 step('Repair the tower signal','repair','Replace the worn bell linkage, repair the ward contacts and test the manual fallback.','The tower signal and its manual fallback both work.',
 '“The ward can fail. I want the person on watch to have another way to warn the road.”',choice('Fit a simple manual bell pull','“Something a cold hand can operate. Yes.”'),choice('Label the fault check beside the mechanism','“Then nobody has to guess which sound means the system itself needs help.”'),crowns=20,materials={'watch-iron':2,'binding-thread':2}),
 step('Prepare and teach the relief team','cipher','Agree the relief rota, teach the signal checks and record who answers a missed handover.','The relief team completes the checks and accepts a rota with a named fallback.',
 '“One keeper asked what happens when she is ill. The old answer was that I stayed.”',choice('Name a second keeper for missed relief','“And let both of them agree. A name on paper is not a promise made by that person.”'),choice('Write a temporary closure and warning procedure','“Then a gap can be handled honestly instead of being hidden in one exhausted person.”'),magic=False),
 step('Test and complete the handover','bargain','Run the warning test with the relief keepers, receive their acknowledgement and sign the handover.','The warning test passes and the relief team formally takes responsibility for the working watch.',
 '“When they answer, I need to let that mean they have answered. I cannot keep inventing one final check.”',choice('Read the completed checklist with her','“Every item. Then we close the book.”'),choice('Wait while she receives the acknowledgement herself','“Thank you. I want to hear it, answer it and leave because the work is finished.”'),magic=False)
 ]),
'merrin':goal('The last act, at last','Recover the missing act of her favourite comedy, bind a complete copy and host its chapel performance.',
 '“It is a two-act comedy. I remember laughing at the ending, but not the ending itself. I want the complete play in my hands and a room of people hearing its last scene. I would like to finish something I can enjoy today.”',
 'chapel','Merrin’s complete chapel reading copy','The missing act is verified, the complete copy is bound and the chapel performance reaches its final scene.',
 'The magistrate finally discovers that he has signed the order to repair his own kitchen roof. The last laugh gives way to applause. Merrin closes the complete book with both hands. “That was the ending. We found it, and we performed it.” She keeps her place beside the others after the reading is over.',
 [choice('Ask whether the ending matched her memory','“The feeling did. I had remembered the cook getting the last word, but it was the scullery maid. I am glad we found the page instead of trusting me.”'),choice('Ask about holding the complete book','“It takes very little attention now. I still put it down before letting go. Finishing the play has not persuaded gravity to make an exception.”')],[
 step('Trace the missing act','search','Compare the chapel account, theatre catalogue and surviving loose scenes.','The catalogue identifies a complete copy in a box of former chapel entertainments.',
 '“I remember a red cover. The catalogue says blue. Please do not discard a blue book on my account.”',choice('Follow the title and scene numbering','“Those can identify the play even when I have borrowed a colour from another memory.”'),choice('Compare the opening lines of each candidate','“Good. The magistrate’s first complaint is unusually specific about onions.”')),
 step('Verify the recovered ending','cipher','Sort the loose pages and distinguish the original final act from a later adaptation.','The original final act is identified; the later adaptation is preserved separately.',
 '“There are two endings. I prefer one joke in the later version. That does not make it the page I came looking for.”',choice('Keep the original text and append the adaptation','“Then the reading copy tells us what each version is. We can still laugh at both.”'),choice('Prepare the original for the first performance','“Yes. I would like to hear the complete play once before changing its last joke.”')),
 step('Bind and rehearse the full play','repair','Bind a durable reading copy, assign willing readers and rehearse through the last scene.','The complete copy is bound and the cast has rehearsed the final act.',
 'Merrin holds a loose page between faintly translucent fingers. “I can press against it by concentrating. Familiar motions are easy. Fine binding work still needs breaks.”',choice('Offer to hold the pages while she sews','“Thank you. I can do the stitches; holding the whole stack steady at the same time was the difficult part.”'),choice('Arrange a support so she can work at her own pace','“That leaves both hands for the thread. Yes. I would rather change the worktable than pretend I never tire.”'),crowns=10,materials={'binding-thread':2}),
 step('Host the chapel performance','bargain','Arrange the chairs, invite willing listeners and perform every scene through the final curtain.','The full play is performed in the chapel, including the recovered ending.',
 '“The register is shut. Tonight this room is for a comedy. Would you take a part, or sit where I can see you laughing?”',choice('Take the magistrate’s part','“Then please complain about the onions with the authority of a man who has never peeled one.”'),choice('Join the audience','“I would like that. You have already heard the rehearsal; I hope we can still surprise you.”'),magic=False)
 ])}
